# Configuration d'un serveur Nginx qui sert les reponses du backend
http {
    # Active la compression gzip
    gzip on;

    # Ne compresse pas les reponses plus petites que 1 Ko (gain trop faible)
    gzip_min_length 1024;

    # Ne compresse QUE les types texte ; les images/videos sont deja compressees
    gzip_types text/plain text/css application/json application/javascript image/svg+xml;

    # Indique aux caches que la reponse varie selon Accept-Encoding
    gzip_vary on;

    # Brotli (si le module est installe) : souvent meilleur sur le texte
    brotli on;
    brotli_min_length 1024;
    brotli_types text/plain text/css application/json application/javascript image/svg+xml;
}
